#pragma once
int runClick463(const char* path,const char* configuration){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;LibraryStore::root().createDirectory();std::cout.setf(std::ios::unitbuf);try{auto require=[](bool ok,const char* text){if(!ok)throw std::runtime_error(text);};Processor p(false);p.autoSave=false;p.isContentionEngine=true;auto data=p.readAudio(juce::File(path));require(data!=nullptr,"read real example");p.audio=data;auto xml=juce::parseXML(juce::File(configuration));require(xml&&p.applyConfiguration(*xml,true),"apply user's saved configuration");p.normaliseEnabled=false;p.swingLinked=false;auto loop=renderLoopAudio(AudioExportSnapshot::capture(p));require(loop.getNumSamples()>0,"render saved loop");writeRenderedAudio(LibraryStore::root().getChildFile("saved-loop.wav"),loop,data->rate);std::cout<<"Source "<<data->rate<<" Hz, "<<data->buffer.getNumSamples()<<" frames; saved loop "<<loop.getNumSamples()<<" frames\n";
 juce::String csv="slice,rate,pitch,fade_ms,frames,end_frame_left,end_frame_right,post_end_peak\n";float worstEnd=0,worstTail=0;int cases=0;juce::AudioBuffer<float> montage(2,(int)(data->rate*8));montage.clear();int montagePos=0;
 for(double rate:{44100.,48000.})for(double pitch:{-12.,0.,12.})for(double fade:{5.,20.,127.6}){p.pitchSemitones=pitch;p.playMode=false;p.sequenceEnabled=false;p.prepareToPlay(rate,128);for(int i=0;i<(int)p.slices.size()&&p.slices[i].start<p.regionEnd();++i){for(auto& v:p.voices)v={};auto& s=p.slices[i];s.endFadeMs=fade;double step=data->rate/rate*std::pow(2.,pitch/12);int frames=(int)std::ceil((s.audibleEnd(data->rate)-s.start)/step-1e-9);int count=frames+(int)(rate*.02);juce::AudioBuffer<float> output(2,count);output.clear();if(std::getenv("SLICE_GROUPS_CLICK_AUDITION"))p.audition(i);else p.startVoice(s,1);for(int offset=0;offset<count;offset+=128){int n=juce::jmin(128,count-offset);juce::AudioBuffer<float> block(2,n);juce::MidiBuffer input;p.processBlock(block,input);for(int ch=0;ch<2;++ch)output.copyFrom(ch,offset,block,ch,0,n);}float end=juce::jmax(std::abs(output.getSample(0,frames-1)),std::abs(output.getSample(1,frames-1))),tail=output.getMagnitude(frames,count-frames);worstEnd=juce::jmax(worstEnd,end);worstTail=juce::jmax(worstTail,tail);csv+=juce::String(i)+","+juce::String(rate,0)+","+juce::String(pitch,0)+","+juce::String(fade,1)+","+juce::String(frames)+","+juce::String(output.getSample(0,frames-1),10)+","+juce::String(output.getSample(1,frames-1),10)+","+juce::String(tail,10)+"\n";++cases;if(rate==44100&&pitch==0&&fade==127.6){int keep=juce::jmin(count,montage.getNumSamples()-montagePos);if(keep>0){for(int ch=0;ch<2;++ch)montage.copyFrom(ch,montagePos,output,ch,0,keep);montagePos+=keep+(int)(rate*.08);}}}}
 LibraryStore::root().getChildFile("slice-endpoints.csv").replaceWithText(csv);montage.setSize(2,juce::jmin(montagePos,montage.getNumSamples()),true);writeRenderedAudio(LibraryStore::root().getChildFile("individual-slices.wav"),montage,44100);std::cout<<"Cases "<<cases<<"; worst final frame "<<worstEnd<<" ("<<juce::Decibels::gainToDecibels(worstEnd)<<" dBFS), post-end peak "<<worstTail<<" ("<<juce::Decibels::gainToDecibels(worstTail)<<" dBFS)\n";if(std::getenv("SLICE_GROUPS_CLICK_REQUIRE_ZERO"))require(worstEnd<1e-8f&&worstTail<1e-8f,"all fades end at exact silence without a residual tail");return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4631;}}
